begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(26);
insert into auth.users(id,email) values ('11111111-1111-4111-8111-111111111111','rc-test@example.invalid'),('22222222-2222-4222-8222-222222222222','rc-coach@example.invalid');
insert into public.profiles(user_id,plan_tier) values ('11111111-1111-4111-8111-111111111111','free'),('22222222-2222-4222-8222-222222222222','coach') on conflict(user_id) do update set plan_tier=excluded.plan_tier;
insert into public.rc_product_config values ('test-app','APP_STORE','PRODUCTION','intentus_executive_monthly',true),('test-app','APP_STORE','PRODUCTION','intentus_premium_monthly',true);
select ok(not has_function_privilege('anon','public.rc_apply_event(text,uuid,text,text,text,text,text,timestamptz,timestamptz)','EXECUTE'),'anon cannot fulfill');
select ok(not has_function_privilege('authenticated','public.recompute_user_plan(uuid)','EXECUTE'),'authenticated cannot recompute');
select ok(not has_table_privilege('authenticated','public.rc_product_config','UPDATE'),'clients cannot allowlist');
set local role service_role;
select is(public.rc_apply_event('one','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','RENEWAL',now()-interval '1 minute',now()+interval '1 day'),'applied','grant applied');
select is((select plan_tier::text from public.profiles where user_id='11111111-1111-4111-8111-111111111111'),'exec','canonical executive');
select is(public.rc_apply_event('one','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','RENEWAL',now()-interval '1 minute',now()+interval '1 day'),'duplicate','retry idempotent');
select throws_ok($$select public.rc_apply_event('one','22222222-2222-4222-8222-222222222222','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','RENEWAL',now()-interval '1 minute',now()+interval '1 day')$$,'22023','event ID collision','cross-user collision rejected');
select is(public.rc_apply_event('old','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','EXPIRATION',now()-interval '2 minutes',now()-interval '2 minutes'),'stale','old expiry ignored');
select is(public.rc_apply_event('cancel','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','CANCELLATION',now(),null),'ignored','cancel no revoke');
select is(public.rc_apply_event('billing','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','BILLING_ISSUE',now(),null),'ignored','billing no revoke');
select is(public.rc_apply_event('sandbox','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','SANDBOX','intentus_executive_monthly','RENEWAL',now(),now()+interval '1 day'),'unconfigured','sandbox denied');
select is(public.rc_apply_event('wrong-app','11111111-1111-4111-8111-111111111111','wrong-app','APP_STORE','PRODUCTION','intentus_executive_monthly','RENEWAL',now(),now()+interval '1 day'),'unconfigured','app binding');
select throws_ok($$select public.rc_apply_event('no-exp','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','RENEWAL',now(),null)$$,'22023','future expiration required','upgrade needs expiry');
select is((select count(*)::integer from public.rc_events where event_id='no-exp'),0,'failure rolls event back');
-- Simulate elapsed source time, then apply an authoritative expiry.
update public.rc_entitlement_sources set expires_at=now()-interval '1 second' where source like 'revenuecat:%';
insert into public.coach_clients(coach_user_id,client_user_id,assigned_tier) values ('22222222-2222-4222-8222-222222222222','11111111-1111-4111-8111-111111111111','premium');
select is(public.rc_apply_event('expire','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','EXPIRATION',now(),now()-interval '1 second'),'applied','matching expiry applied');
select is((select plan_tier::text from public.profiles where user_id='11111111-1111-4111-8111-111111111111'),'premium','coach assignment survives RC expiry');
delete from public.coach_clients where client_user_id='11111111-1111-4111-8111-111111111111';
select is(public.recompute_user_plan('11111111-1111-4111-8111-111111111111')::text,'free','new user fully revoked when sources gone');
select is(public.recompute_user_plan('22222222-2222-4222-8222-222222222222')::text,'coach','legacy coach preserved');
select is((select count(*)::integer from public.rc_events where event_id='one'),1,'durable single event');
select is((select count(*)::integer from public.rc_entitlement_sources where user_id='11111111-1111-4111-8111-111111111111' and source='legacy'),0,'RC and aggregation do not create legacy');
insert into public.rc_product_config values ('test-app','APP_STORE','SANDBOX','intentus_premium_monthly',true);
select is(public.rc_apply_event('sandbox-allowed','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','SANDBOX','intentus_premium_monthly','RENEWAL',now(),now()+interval '1 day'),'applied','explicit sandbox configuration honored');
insert into public.rc_entitlement_sources(user_id,source,product_id,tier,active) values ('11111111-1111-4111-8111-111111111111','other-provider','coach-product','coach',true);
select is(public.recompute_user_plan('11111111-1111-4111-8111-111111111111')::text,'coach','other provider coach survives');
select is(public.rc_apply_event('unknown','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','arbitrary_coach','RENEWAL',now(),now()+interval '1 day'),'unconfigured','unknown product cannot upgrade');
select throws_ok($$select public.rc_apply_event('future','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','RENEWAL',now()+interval '1 day',now()+interval '2 days')$$,'22023','invalid event','future event rejected');
select is(public.rc_apply_event('change','11111111-1111-4111-8111-111111111111','test-app','APP_STORE','PRODUCTION','intentus_executive_monthly','PRODUCT_CHANGE',now(),null),'ignored','scheduled product change does not grant');
reset role;
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.recompute_user_plan(uuid)'::regprocedure),'fixed search path');
select * from finish();
rollback;
